 	gitUpdateRef   = "update-ref"
 	gitForEachRef  = "for-each-ref"

 	// testHeadHash is an arbitrary valid-looking SHA-1 used as a fixture in the
 	// runGitFn fakes below.
 	testHeadHash = "20b4de1033d986a83837177f961c80bb799161e6"
