 		if refLookupAbsent(err, stderr) {
 			return nil, plumbing.ErrReferenceNotFound
 		}
 		return nil, fmt.Errorf("reftable resolve ref %s: %s: %w", name, strings.TrimSpace(string(stderr)), err)
 	}
 	if out == "" {
 		return nil, plumbing.ErrReferenceNotFound
 	}
 	h := plumbing.NewHash(out)
 	if h.IsZero() {
 		return nil, plumbing.ErrReferenceNotFound
 	}
