 		// Symbolic refs (e.g. HEAD) have no CAS form in update-ref; set directly.
 		return s.SetReference(newRef)
 	}
 	if old == nil {
 		return s.SetReference(newRef)
 	}
 	_, stderr, err := s.runGit("update-ref", "--end-of-options", newRef.Name().String(), newRef.Hash().String(), old.Hash().String())
