 		return nil, plumbing.ErrReferenceNotFound
 	}
 	h := plumbing.NewHash(out)
 	if h.IsZero() {
 		return nil, plumbing.ErrReferenceNotFound
 	}
 	return plumbing.NewHashReference(name, h), nil
