    39	// casUpdateRef atomically updates refName through native Git's lock protocol.
    40	// Pass ZeroHash as expectedHash to require that the ref does not exist.
    41	func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
    42		newValue := newHash.String()
    43		oldValue := strings.Repeat("0", newHash.HexSize())
