   126				newHash, expectedHash, buildErr := build()
   127				if buildErr != nil {
   128					return buildErr
   129				}
   130	
   131				refErr := casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
   132				if refErr == nil {
   133					return nil
   134				}
   135				if !errors.Is(refErr, ErrShadowRefBusy) {
   136					return fmt.Errorf("update persistent ref %s: %w", refName, refErr)
   137				}
