   816			actual := plumbing.ZeroHash
   817			if cur, refErr := repo.Reference(refName, true); refErr == nil {
   818				actual = cur.Hash()
   819			}
   820			return &V1RefMovedError{Expected: expectedOld, Actual: actual}
   821		}
   822		return fmt.Errorf("set v1 ref: %w", err)
   823	}

