   789	func readBlob(repo *git.Repository, hash plumbing.Hash) ([]byte, error) {
   790		blob, err := repo.BlobObject(hash)
   791		if err != nil {
   792			return nil, fmt.Errorf("blob: %w", err)
   793		}
